    "description": "Відкрита місцевість, де дощ падає постійно, але жодна крапля не торкається землі: вода зависає на різній висоті й утворює вертикальні завіси. Рельєф складається з м'яких пагорбів, кам'яних гребенів і низин, наповнених підвішеними краплями.",
    "flora": "Рослинність має широке листя у формі чаш, що збирають завислу воду, і тонкі дерева з прозорими кронами.",
