    "description": "Рівна безкрая місцевість, де дерева ростуть кронами вниз, а їхні корені піднімаються в небо й розгалужуються у формі величезних дерев'яних антен. Підвішені крони утворюють зелені стелі на різній висоті, тоді як на землі простягаються золотаві трави та низькі кам'яні гряди.",
    "flora": "Мешканці — перевернуті білки, крилаті олені та кореневі павуки.",
    "structures": [
      "Старі селища побудовані на платформах, прикріплених до кореневих систем, а дороги проходять по мотузкових мостах і дерев'яних драбинах.",
      "Деякі корені слугують підйомниками, а плоди можна збирати й використовувати як тимчасові повітряні платформи."
    ],
    "special": "У повітрі висять плоди, які повільно опускаються до землі, перш ніж знову підійматися до гілок. Сонце проходить крізь підвішені крони, утворюючи на землі рухомі мозаїки світла.",
